#include <vector>
#include <iostream>
#include <cassert>
using namespace std;
int pw(int a,int n,int p){int b=1;for(;n;n>>=1,a=a*a%p)if(n&1)b=b*a%p;return b;}
int ch(int n,int k){int b=1;for(int i=1;i<=k;i++)b=b*(n-i+1)/i;return b;}
int main(){int banks;cin>>banks;cout<<"[";for(int bank=0;bank<banks;bank++){int p,np;cin>>p>>np;vector<int>x(14),y(14);for(int&a:x)cin>>a;for(int&a:y)cin>>a;vector<pair<int,int>>cols;for(int j=0;j<=8;j++)for(int k=0;k<=3*j+3;k++)cols.push_back({k,8-j});assert(cols.size()==144);if(bank)cout<<",";cout<<"{\"prime\":"<<p<<",\"cases\":[";for(int pat=0;pat<np;pat++){vector<int>m(14);for(int&a:m)cin>>a;vector<vector<int>>a;for(int i=0;i<14;i++)for(int h=0;h<m[i];h++)for(int dx=0;dx<=h;dx++){int dy=h-dx;vector<int>r;for(auto [k,l]:cols)r.push_back(k<dx||l<dy?0:1LL*(ch(k,dx)%p)*(ch(l,dy)%p)%p*pw(x[i],k-dx,p)%p*pw(y[i],l-dy,p)%p);a.push_back(r);}int rank=0,det=1;vector<int>rowid(a.size()),prs,pcs;for(int i=0;i<(int)a.size();i++)rowid[i]=i;for(int c=0;c<144;c++){int k=rank;while(k<(int)a.size()&&!a[k][c])k++;if(k==(int)a.size())continue;swap(a[k],a[rank]);swap(rowid[k],rowid[rank]);prs.push_back(rowid[rank]);pcs.push_back(c);int pivot=a[rank][c];det=det*pivot%p;int iv=pw(pivot,p-2,p);for(int j=c;j<144;j++)a[rank][j]=a[rank][j]*iv%p;for(int i=rank+1;i<(int)a.size();i++)if(a[i][c]){int f=a[i][c];for(int j=c;j<144;j++)a[i][j]=(a[i][j]+p*p-f*a[rank][j])%p;}rank++;}if(pat)cout<<",";cout<<"{\"rank\":"<<rank<<",\"pivot_product\":"<<det<<",\"rows\":[";for(int i=0;i<rank;i++){if(i)cout<<",";cout<<prs[i];}cout<<"],\"columns\":[";for(int i=0;i<rank;i++){if(i)cout<<",";cout<<pcs[i];}cout<<"]}";}cout<<"]}";}cout<<"]\n";}
